function validateCursor(before: unknown): {cursor: SessionCursor} | {error: string} {
  if (typeof before !== 'object' || before === null) {
    return {error: 'list_sessions before must be an object'};
  }
  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_CURSOR_ID_LENGTH) {
    return {error: `list_sessions before.sessionId must be 1-${MAX_CURSOR_ID_LENGTH} characters`};
  }
  const isDateLike = typeof updatedAt === 'string' || typeof updatedAt === 'number';
  if (!isDateLike || !Number.isFinite(new Date(updatedAt).getTime())) {
    return {error: 'list_sessions before.updatedAt must be a valid date'};
  }
  return {cursor: {updatedAt, sessionId}};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit} = message;
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0)) {
